args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:To_Live_in_Peace dbo:director ?director .
  ?director dbo:deathPlace ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER (lang(?deathPlaceLabel) = 'en') }
}

